from aerelith.core.result import Result

def batch_apply(rows, n, fn):
    if n < 1:
        return Result(ok=False, value=None, err='E_RANGE')
    batches = chunked(rows, n)
    results = []
    for batch in batches:
        result = fn(batch)
        if not result.ok:
            return result
        results.extend(result.value)
    return Result(ok=True, value=results, err=None)

