function dedupeById(rows) {
  if (!Array.isArray(rows)) return null;

  const seenIds = new Set();
  const dedupedRows = [];

  for (const row of rows) {
    if (!seenIds.has(row.id)) {
      seenIds.add(row.id);
      dedupedRows.push(row);
    }
  }

  return dedupedRows;
}

module.exports = { dedupeById };
