export function pickKeys<T extends object, K extends keyof T>(row: T, keys: readonly K[]): Result<{ [P in K]: T[P] }> {
  if (keys.length === 0) return { ok: false, error: 'no keys' };
  const picked: Partial<{ [P in K]: T[P] }> = {};
  for (const key of keys) {
    picked[key] = row[key];
  }
  return { ok: true, value: picked as { [P in K]: T[P] } };
}

